    ('dbdf34b2-64b9-5949-9212-ea99b56cabba'::uuid, '885cd9d1-5efb-536a-9b9b-97259bb080a0'::uuid, 'Recycler un objet est le meilleur moyen de réduire son impact.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Allonger sa durée de vie et ne pas le produire sont plus efficaces.', 8),
