    ('3d7e8bf0-0940-5373-b7e3-31b3e0bf0912'::uuid, '831a9615-cb1d-5ec9-ab20-d371831d4019'::uuid, 'Que décide-t-on en choisissant la colle plutôt que la vis ?', 'mcq', '["Que l’objet ne sera pratiquement pas réparable","Qu’il sera moins cher à l’usage","Qu’il durera plus longtemps","Rien de particulier"]'::jsonb, 0, 'C’est un choix de durée de vie.', 3),
    ('5d32f4eb-0946-59d9-94a2-7c5c9d298cca'::uuid, '831a9615-cb1d-5ec9-ab20-d371831d4019'::uuid, 'Qu’est-ce que la tolérance ?', 'mcq', '["L’écart acceptable autour de la cote","Le temps de fabrication","Le prix maximal","La dureté du matériau"]'::jsonb, 0, 'Une pièce hors tolérance est refusée.', 4),
