    ('fe83db29-b78a-574a-813d-c22610b95695'::uuid, '5adcc223-ede5-5f74-bf9a-45fa548a4362'::uuid, 'Quelles sont les deux chaînes d’un objet technique ?', 'mcq', '["La chaîne d’information et la chaîne d’énergie","La chaîne de production et de vente","La chaîne de montage et de contrôle","La chaîne mécanique et électrique"]'::jsonb, 0, 'Elles travaillent ensemble.', 1),
    ('d060f4bd-cf4c-5b0d-8846-5c55f1cacd9d'::uuid, '5adcc223-ede5-5f74-bf9a-45fa548a4362'::uuid, 'Que fait un capteur ?', 'mcq', '["Il transforme une grandeur physique en signal","Il produit du mouvement","Il stocke l’énergie","Il éclaire"]'::jsonb, 0, 'Température, lumière, présence.', 2),
