    ('4a724b91-5845-53bb-96b5-3ded1acbec3e'::uuid, '5adcc223-ede5-5f74-bf9a-45fa548a4362'::uuid, 'Quelles sont les fonctions de la chaîne d’énergie ?', 'mcq', '["Alimenter, distribuer, convertir, transmettre","Acquérir, traiter, communiquer","Tracer, découper, assembler","Voir, décider, agir"]'::jsonb, 0, 'De la pile jusqu’aux engrenages.', 5),
    ('9e418404-d6fe-53be-aa09-17c5b7d6c6e1'::uuid, '5adcc223-ede5-5f74-bf9a-45fa548a4362'::uuid, 'Quel élément décide selon le programme ?', 'mcq', '["La carte programmable","Le capteur","L’actionneur","La pile"]'::jsonb, 0, 'C’est le microcontrôleur.', 6),
    ('7b868e54-6b02-5b4d-84f2-e62969d274ce'::uuid, '5adcc223-ede5-5f74-bf9a-45fa548a4362'::uuid, 'Pourquoi distingue-t-on les deux chaînes ?', 'mcq', '["Pour localiser une panne : information ou énergie","Par tradition","Pour réduire le prix","Pour accélérer la fabrication"]'::jsonb, 0, 'Cela divise le problème en deux.', 7),
